"""Fresh method-scoped independent reviewer or same-method revision author."""
import argparse,json,subprocess,time
from pathlib import Path
RUN=Path(__file__).resolve().parents[1]
def main():
    p=argparse.ArgumentParser();p.add_argument('--method',choices=['M1','M2','M3','M4'],required=True);p.add_argument('--phase',choices=['initial_review','final_review','repair'],required=True);p.add_argument('--label');a=p.parse_args()
    root=RUN/'models'/a.method;phase=a.phase;label=a.label or f'{a.method.lower()}_{phase}'
    common=f'''You are fresh GPT-6 Astra in a user-authorized independent Blender experiment, method {a.method} ONLY. Read {RUN}/configs/modelling_contract.md. Allowed reads ONLY {RUN}/inputs/{a.method}/, {root}/, that contract, and generic tools {RUN}/tools/paired_check_blender.py, visualize_checks.py, raycast_scene.py, depth_math.py, inspect_scene.py, validate_artifacts.py. No parent experiment/plans, GT scene/depth, old experiment models, heldout data, evaluation metrics, web, other methods, global processes or /proc. No subagents. Filesystem unrestricted but method-scoped tools and honest access records required. Do not read root provenance logs (they may contain other contexts).
'''
    if phase=='repair':
        task=f'''You are the {a.method} revision AUTHOR. Read the current v1 model, measured evidence, ten actual paired comparisons and independent initial review. Revise based on concrete multi-view RGB and own input DA3 residuals (M1 RGB only). Up to5 full versions total. Every new geometry version must increment revisions, retain snapshots, run ALL ten exact paired checks then visualize/inspect them. Do not move input cameras or remove difficult input masks. M2–M4 need exactly3 total full180 BVH passes: v1 exists; run one after main repairs and one on final candidate, separate directories checks/input_v2 and checks/input_final (even same geometry allowed, explain no geometry change). Respect max3. Mark uncertain/inferred parameters and record each dimension/position adjustment with frames/pixel regions/signed depth residuals and before/after parameters. Review technical blockers must be fixed; visual approximation can remain LIMITED with evidence. Ensure semantic component_names cover all real scene meshes, collider proxies correspond to logical objects and traversable portals, cameras and manifests valid. Generate .blend and .glb with build_scene.py from scratch, validate artifacts. Save author_repair_notes.md/json and return final candidate with actual hashes, no self-certified independent review or freeze. Tools use2CPUthreads12samples. Do not stop with merely a plan; finish a reviewable repaired candidate. Write ONLY {root}/.'''
    else:
        final=phase=='final_review';name='final_review' if final else 'initial_review'
        task=f'''You are the INDEPENDENT {'FINAL' if final else 'INITIAL'} REVIEWER, not author. Write ONLY {root}/independent_review/. Do not modify geometry, scripts or manifests. Do not run additional visual renders; reuse ten fixed paired checks. Review current .blend/.glb and records with actual source images/contact sheets and actual paired comparison sheets, model/input depth residuals, camera projection/units, semantic IDs/components, normals, major penetration/support/portal passage/collision proxies, and evidence/uncertainty. Fixed samples33,61,74,82,91,100,108,118,129,155. Use scene inspection generic tool to your review folder if needed; no additional input BVH passes. Check paired version records match current model SHA256 and all versions had10 views. For final, read initial issues and author repairs and independently check final candidate, three full180 input passes for geometry methods, budget <=5versions50paired views, input scale/camera unchanged. Report finite actionable object/frame-specific findings; visual limitations are allowed LIMITED, actual corruptions, invalid projection, missing required evidence or protocol leaks are technical_protocol_blockers. Save {name}.json and {name}.md with method_id, reviewer_model='gpt-6-astra', independent_fresh_context=true, actual model_sha256, status PASS/PASS_WITH_LIMITATIONS/LIMITED/BLOCKED, review_complete=true only when evidence inspected, technical_protocol_blockers list, issues with object/frame/evidence/severity/recommendation and paths_read. Final review must explicitly revisit initial issues. Bounded review: inspect sufficient actual images and geometry to support conclusions, then write results promptly and finish, don't indefinitely expand scope. No GT access or feedback. Do not fabricate checks. Return concise actionable findings.'''
    prompt=common+task
    (RUN/f'provenance/{label}_prompt.txt').write_text(prompt)
    cmd=['codex','exec','-m','gpt-6-astra','-c','model_reasoning_effort="high"','-c','approval_policy="never"','--sandbox','danger-full-access','--skip-git-repo-check','--json','--color','never','-C',str(root),'-o',str(RUN/f'provenance/{label}_final.txt'),'-']
    (RUN/f'provenance/{label}_launch.json').write_text(json.dumps(dict(model='gpt-6-astra',fresh_context=True,method=a.method,phase=phase,started_utc=time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime())),indent=2)+'\n')
    with (RUN/f'provenance/{label}_events.jsonl').open('w') as log,(RUN/f'provenance/{label}_stderr.log').open('w') as err:
        result=subprocess.run(cmd,input=prompt,text=True,stdout=log,stderr=err)
    print(label,result.returncode);raise SystemExit(result.returncode)
if __name__=='__main__':main()
